package servicos;
import java.text.NumberFormat; import java.text.ParseException; import java.text.SimpleDateFormat; import java.util.Date; import java.util.Locale;
public final class FormatoUtil { private FormatoUtil(){} public static Double valor(String texto){try{String t=texto==null?"":texto.replace("R$","").replaceAll("\\s","");if(t.isEmpty())return null;if(t.indexOf(',')>=0)t=t.replace(".","").replace(',','.');double v=Double.parseDouble(t);return v>0&&!Double.isInfinite(v)&&!Double.isNaN(v)?v:null;}catch(NumberFormatException e){return null;}} public static String moeda(Double v){return NumberFormat.getCurrencyInstance(new Locale("pt","BR")).format(v==null?0:v);} public static Date data(String texto)throws ParseException{String d=texto==null?"":texto.replaceAll("\\D","");if(d.length()==8)d=d.substring(0,2)+"/"+d.substring(2,4)+"/"+d.substring(4);SimpleDateFormat f=new SimpleDateFormat("dd/MM/yyyy");f.setLenient(false);return f.parse(d);} public static String data(Date d){return d==null?"":new SimpleDateFormat("dd/MM/yyyy").format(d);} }
